activities.codeSnippet:
class Car {
    String model;

    // ⚠️ LOOK CLOSELY: This has 'void'! It is a METHOD, NOT a constructor!
    void Car() {
        this.model = "Ferrari";
        System.out.println("Ordinary method Car() ran!");
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car(); // Calls the compiler's default constructor!

        // The field 'model' is null because void Car() was NEVER called!
        System.out.println("Car model: " + c.model);

        // You have to call it manually like an ordinary method:
        c.Car();
        System.out.println("Car model after method: " + c.model);
    }
}

