class Printer {
    String model;

    Printer(String model) {
        this.model = model;
        System.out.println("[Init] Model: " + model);
    }

    void printDocument(String doc) {
        System.out.println("[Print] Printing " + doc);
    }
}

public class Main {
    public static void main(String[] args) {
        Printer p = new Printer("LaserJet");
        p.printDocument("Resume.pdf");
        p.printDocument("Invoice.pdf");
    }
}

