practiceProblems.solutionCode:
class Session {
    String token;
    boolean isValid;

    Session(String token) {
        if (token == null) {
            isValid = false;
            return;
        }
        this.token = token;
        isValid = true;
    }
}

public class Main {
    public static void main(String[] args) {
        Session s1 = new Session(null);
        Session s2 = new Session("JWT-123");
        System.out.println("S1 valid: " + s1.isValid + " | S2 valid: " + s2.isValid);
    }
}

class Message {
    String content;

    Message(String content) {
        this.content = content;
    }

    String Message() {
        return "Echo: " + this.content;
    }
}

public class Main {
    public static void main(String[] args) {
        Message m = new Message("Hello World");
        System.out.println("Constructor set: " + m.content);
        System.out.println("Method returned: " + m.Message());
    }
}
